/**
 * @param {Function} fn
 * @return {Function}
 */
var once = function(fn) {
    let called = false;

    return function(...args) {
        // Already called: do nothing, return undefined
        if (called) return undefined;

        called = true;            // Mark as called before running fn
        return fn(...args);       // First call: forward the arguments
    };
};
